from pathlib import Path

p = Path('src/pages/Products.jsx')
s = p.read_text()

def repl(old,new):
    global s
    if old not in s:
        raise SystemExit('pattern not found:\n'+old[:180])
    s=s.replace(old,new,1)

repl("const EMPTY_FORM = { name:'',price:'',cost:'',category:'other',supplier:'',note:'',spec_mode:'none',spec_colors:[],spec_sizes:[],spec_flavors:[],price_options:[],price_label_input:'',price_value_input:'',price_cost_input:'',color_input:'',size_input:'',flavor_input:'' }",
"const EMPTY_FORM = { name:'',price:'',cost:'',pricing_mode:'single',category:'other',supplier:'',note:'',spec_mode:'none',spec_colors:[],spec_sizes:[],spec_flavors:[],price_options:[],price_label_input:'',price_value_input:'',price_cost_input:'',color_input:'',size_input:'',flavor_input:'' }")

repl("function PriceOptionsEditor({form,setForm}){const[open,setOpen]=useState(false);const count=(form.price_options||[]).length;",
"function PriceOptionsEditor({form,setForm}){const count=(form.price_options||[]).length;const[open,setOpen]=useState(()=>form.pricing_mode==='options'&&count===0);")

